-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.78.1',
  '2026-08-07',
  'Версия приложения в меню и порядок с версиями страниц',
  E'Администратору в левом меню рядом с заголовком «Habits» теперь видна версия приложения — там же, где версии страниц.\n\nЗаодно исправлено упущение: страницам Converter и Главная версии не проставили, хотя правили их в последних двух выпусках. Теперь у них 2.78 и 2.77.',
  E'APP_VERSION выводится в шапке меню под тем же условием isAdmin, что и версии страниц.\n\nПроставлены пропущенные meta.version: converter → 2.78 (правился в этом же выпуске), main → 2.77. Пропуск не случайность, а следствие того, что шаг нигде не был записан.\n\nПоэтому в порядок релиза (skill проекта) добавлен отдельный пункт: проставить meta.version КАЖДОЙ затронутой странице той же версией релиза, без patch, и держать в том же значении заголовок страницы в DOCS.md. Автоматически вывести нельзя: релиз обычно трогает несколько страниц, и «версия релиза» не равна «версии страницы».\n\nПри правке слит дубль селектора .drawer-title — новые свойства сначала легли отдельным блоком поверх существующего.\n\nБез версии осознанно остаются 11 страниц старше журнала изменений (Tracker, Checker, Tasks, Diary, Metrics, Passwords, Reminders, Links, Articles, Help, Settings): выдумывать им «1.0» задним числом не стали.'
);
-- +goose StatementEnd

